1. Create a `TooltipContext` to store the state of the currently opened Tooltip and a function to close it.

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ tooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};
```

2. Wrap the Tooltip component with the TooltipProvider and pass the context value to it.

```jsx
import React from 'react';
import Tooltip from './Tooltip';

const TooltipWrapper = ({ children }) => {
  return (
    <TooltipProvider>
      <Tooltip>{children}</Tooltip>
    </TooltipProvider>
  );
};

export default TooltipWrapper;
```

3. Use the TooltipContext in the Tooltip component to open and close the tooltip.

```jsx
import React, { useContext } from 'react';
import { TooltipContext } from '../TooltipContext';

const Tooltip = ({ children }) => {
  const { tooltip, closeTooltip } = useContext(TooltipContext);

  const [isOpen, setIsOpen] = useState(false);

  const handleMouseEnter = () => {
    setIsOpen(true);
  };

  const handleMouseLeave = () => {
    if (!tooltip) {
      setIsOpen(false);
    }
  };

  const handleClick = () => {
    setIsOpen(!isOpen);
  };

  React.useEffect(() => {
    if (tooltip && tooltip.key === key) {
      setIsOpen(true);
    } else {
      setIsOpen(false);
    }
  }, [tooltip]);

  return (
    <div>
      {React.cloneElement(children, {
        onMouseEnter: handleMouseEnter,
        onMouseLeave: handleMouseLeave,
        onClick: handleClick,
      })}
      {isOpen && (
        <div className="tooltip">{children.props.title}</div>
      )}
    </div>
  );
};

export default Tooltip;
```

4. Use the TooltipWrapper component in your components to wrap the tooltip elements.

```jsx
import React from 'react';
import TooltipWrapper from '../TooltipWrapper';

const TooltipExample = () => {
  return (
    <div>
      <TooltipWrapper>
        <div>Hover over me</div>
      </TooltipWrapper>
      <TooltipWrapper>
        <div>Click me</div>
      </TooltipWrapper>
    </div>
  );
};

export default TooltipExample;
```

Now, the Tooltip component will close the previously opened Tooltip when a new one is opened, and it will only open the Tooltip for the element that is currently being hovered or clicked.

