I'm not sure what you mean by "implement it." Are you asking for a specific algorithm or data structure to solve a problem related to pipes and pays?

If you're asking for a way to model a system with pipes and pays using a programming language, here's a simple example in Python:

```python
class Pipe:
    def __init__(self, capacity):
        self.capacity = capacity
        self.water = 0

    def add_water(self, amount):
        if amount <= self.capacity - self.water:
            self.water += amount
        else:
            self.water = self.capacity

    def drain_water(self, amount):
        if amount <= self.water:
            self.water -= amount
        else:
            self.water = 0

    def get_water(self):
        return self.water

class Pay:
    def __init__(self, amount):
        self.amount = amount
        self.paid = False

    def pay(self):
        if not self.paid:
            self.paid = True
            return self.amount
        else:
            return 0

# Example usage:
pipe1 = Pipe(10)
pipe2 = Pipe(5)
pay1 = Pay(5)
pay2 = Pay(3)

pipe1.add_water(2)
pipe2.add_water(3)

print(f"Pipe 1 has {pipe1.get_water()} liters of water.")
print(f"Pipe 2 has {pipe2.get_water()} liters of water.")

print(f"Pay 1 pays {pay1.pay()} liters.")
print(f"Pay 2 pays {pay2.pay()} liters.")

pipe1.drain_water(5)
print(f"Pipe 1 has {pipe1.get_water()} liters of water.")
print(f"Pipe 2 has {pipe2.get_water()} liters of water.")
