var axios = require('axios');

var apiKey = 'YOUR_API_KEY';
var baseUrl = 'https://openexchangerates.org/api/latest.json?app_id=' + apiKey;

function getRate(fromCurrency, toCurrency) {
  return new Promise((resolve, reject) => {
    axios.get(baseUrl)
      .then(response => {
        var rates = response.data.rates;
        var rate = rates[toCurrency] / rates[fromCurrency];
        resolve(rate);
      })
      .catch(error => {
        reject(error);
      });
  });
}

function formatPrice(price, currency) {
  return price.toFixed(2) + ' ' + currency;
}

