  return new Promise((resolve, reject) => {
    getRate(fromCurrency, toCurrency)
      .then(rate => {
        var convertedPrice = price * rate;
        resolve(formatPrice(convertedPrice, toCurrency));
      })
      .catch(error => {
        reject(error);
      });
  });
}

