To convert an object to a Data Transfer Object (DTO) without using Spring, you can use plain Java. Here's a simple example using Java's reflection API:

```java
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public class ObjectToDtoConverter {
    public static <T, D> List<D> convert(List<T> objects, Class<D> dtoClass) {
        List<D> dtos = new ArrayList<>();
        for (T object : objects) {
            try {
                D dto = dtoClass.newInstance();
                Field[] fields = dtoClass.getDeclaredFields();
                for (Field field : fields) {
                    field.setAccessible(true);
                    field.set(dto, getFieldValue(object, field.getName()));
                }
                dtos.add(dto);
            } catch (InstantiationException | IllegalAccessException e) {
                e.printStackTrace();
            }
        }
        return dtos;
    }

    private static Object getFieldValue(Object object, String fieldName) {
        try {
            Field field = object.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(object);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            e.printStackTrace();
            return null;
        }
    }
}
```

